  columns?: DataplexDataScan_DataQualityResult_Columns[] | Computed<DataplexDataScan_DataQualityResult_Columns[]>;
  /** Output only. A list of results at the dimension level.A dimension will have a corresponding DataQualityDimensionResult if and only if there is at least one rule with the 'dimension' field set to it. */
  dimensions?: DataplexDataScan_DataQualityResult_Columns_Dimensions[] | Computed<DataplexDataScan_DataQualityResult_Columns_Dimensions[]>;
